const char* rcc_parser_cxx_current_namespace_identity(void) {
    return cxx_namespace_typeinfo_identity(active_namespace);
}

static CxxNamespace* cxx_namespace_find_typeinfo_identity(
    CxxNamespace* ns, const char* identity) {
    const char* current_identity;
    if (!ns || !identity) return NULL;
    current_identity = cxx_namespace_typeinfo_identity(ns);
    if (current_identity && strcmp(current_identity, identity) == 0) {
        return ns;
    }
    for (CxxNamespace* child = ns->children; child; child = child->next) {
        CxxNamespace* found =
            cxx_namespace_find_typeinfo_identity(child, identity);
        if (found) return found;
    }
    return NULL;
}

bool rcc_parser_cxx_type_namespace_matches_qualified_name(
    const char* declaration_identity, const char* qualified_name) {
    CxxNamespace* declaration_namespace;
    CxxNamespace* qualified_namespace;
    if (!g_global_namespace || !declaration_identity || !qualified_name) {
        return false;
    }
    declaration_namespace = cxx_namespace_find_typeinfo_identity(
        g_global_namespace, declaration_identity);
    qualified_namespace = cxx_namespace_find(g_global_namespace,
                                               qualified_name);
    return declaration_namespace && declaration_namespace ==
        qualified_namespace;
}

typedef struct CxxNamespaceTypeLookupPath {
    CxxNamespace* ns;
    const struct CxxNamespaceTypeLookupPath* parent;
} CxxNamespaceTypeLookupPath;

static bool cxx_namespace_type_lookup_contains(
    CxxNamespace* lookup_namespace, CxxNamespace* declaration_namespace,
    const CxxNamespaceTypeLookupPath* path) {
    CxxNamespaceTypeLookupPath current_path;
    if (!lookup_namespace || !declaration_namespace) return false;
    for (const CxxNamespaceTypeLookupPath* entry = path; entry;
         entry = entry->parent) {
        if (entry->ns == lookup_namespace) return false;
    }
    if (lookup_namespace == declaration_namespace) return true;
    for (CxxNamespace* imported = declaration_namespace;
         imported && (imported->is_inline_namespace ||
                      imported->is_anonymous_namespace);
         imported = imported->parent) {
        if (imported->parent == lookup_namespace) return true;
    }
    current_path.ns = lookup_namespace;
    current_path.parent = path;
    for (CxxNamespace* child = lookup_namespace->children; child;
         child = child->next) {
        if ((child->is_inline_namespace || child->is_anonymous_namespace) &&
            cxx_namespace_type_lookup_contains(
                child, declaration_namespace, &current_path)) {
            return true;
        }
    }
    for (int index = 0; index < lookup_namespace->using_namespace_count;
         ++index) {
        if (cxx_namespace_type_lookup_contains(
                lookup_namespace->using_namespaces[index],
                declaration_namespace, &current_path)) {
            return true;
        }
    }
    return false;
}

static bool cxx_namespace_type_lookup_directly_contains(
    CxxNamespace* lookup_namespace, CxxNamespace* declaration_namespace,
    const CxxNamespaceTypeLookupPath* path) {
    CxxNamespaceTypeLookupPath current_path;
    if (!lookup_namespace || !declaration_namespace) return false;
    for (const CxxNamespaceTypeLookupPath* entry = path; entry;
         entry = entry->parent) {
        if (entry->ns == lookup_namespace) return false;
    }
    if (lookup_namespace == declaration_namespace) return true;
    for (CxxNamespace* imported = declaration_namespace;
         imported && (imported->is_inline_namespace ||
                      imported->is_anonymous_namespace);
         imported = imported->parent) {
        if (imported->parent == lookup_namespace) return true;
    }
    current_path.ns = lookup_namespace;
    current_path.parent = path;
    for (CxxNamespace* child = lookup_namespace->children; child;
         child = child->next) {
        if ((child->is_inline_namespace || child->is_anonymous_namespace) &&
            cxx_namespace_type_lookup_directly_contains(
                child, declaration_namespace, &current_path)) {
            return true;
        }
    }
    return false;
}

static CxxNamespace* cxx_namespace_common_ancestor(CxxNamespace* left,
                                                   CxxNamespace* right) {
    for (CxxNamespace* ancestor = left; ancestor;
         ancestor = ancestor->parent) {
        for (CxxNamespace* candidate = right; candidate;
             candidate = candidate->parent) {
            if (ancestor == candidate) return ancestor;
        }
    }
    return NULL;
}

bool rcc_parser_cxx_type_namespace_is_visible(
    const char* declaration_identity, const char* current_identity) {
    CxxNamespace* declaration_namespace;
    CxxNamespace* current_namespace;
    if (!g_global_namespace) return false;
    declaration_namespace = declaration_identity && *declaration_identity
        ? cxx_namespace_find_typeinfo_identity(
              g_global_namespace, declaration_identity)
        : g_global_namespace;
    current_namespace = current_identity && *current_identity
        ? cxx_namespace_find_typeinfo_identity(
              g_global_namespace, current_identity)
        : g_global_namespace;
    if (!declaration_namespace || !current_namespace) return false;
    for (CxxNamespace* scope = current_namespace; scope;
         scope = scope->parent) {
        if (cxx_namespace_type_lookup_contains(
                scope, declaration_namespace, NULL)) return true;
    }
    return false;
}

void rcc_parser_cxx_type_namespace_lookup_depths(
    const char* declaration_identity, const char* current_identity,
    int* direct_depth, int* using_depth) {
    CxxNamespace* declaration_namespace;
    CxxNamespace* current_namespace;
    if (direct_depth) *direct_depth = -1;
    if (using_depth) *using_depth = -1;
    if (!g_global_namespace || !direct_depth || !using_depth) return;
    declaration_namespace = declaration_identity && *declaration_identity
        ? cxx_namespace_find_typeinfo_identity(
              g_global_namespace, declaration_identity)
        : g_global_namespace;
    current_namespace = current_identity && *current_identity
        ? cxx_namespace_find_typeinfo_identity(
              g_global_namespace, current_identity)
        : g_global_namespace;
    if (!declaration_namespace || !current_namespace) return;
    {
        int depth = 0;
        for (CxxNamespace* scope = current_namespace; scope;
             scope = scope->parent, ++depth) {
            if (*direct_depth < 0 &&
                cxx_namespace_type_lookup_directly_contains(
                    scope, declaration_namespace, NULL)) {
                *direct_depth = depth;
            }
            for (int index = 0; index < scope->using_namespace_count;
                 ++index) {
                CxxNamespace* nominated = scope->using_namespaces[index];
                CxxNamespace* effective_scope =
                    cxx_namespace_common_ancestor(scope, nominated);
                int effective_depth = 0;
                bool is_ancestor = false;
                if (!effective_scope ||
                    !cxx_namespace_type_lookup_contains(
                        nominated, declaration_namespace, NULL)) {
                    continue;
                }
                for (CxxNamespace* lookup = current_namespace; lookup;
                     lookup = lookup->parent, ++effective_depth) {
                    if (lookup == effective_scope) {
                        is_ancestor = true;
                        break;
                    }
                }
                if (is_ancestor &&
                    (*using_depth < 0 || effective_depth < *using_depth)) {
                    *using_depth = effective_depth;
                }
            }
        }
    }
}

/* A leading alignas belongs to a class declaration only when its complete
 * parenthesized argument list is followed by class-key.  Leave other
 * declarations to the common declaration parser so alignas on objects and
 * functions keeps its existing semantics. */
static bool cxx_leading_alignas_class_starts(void) {
    Token* token = parser.cur;
    bool saw_alignas = false;

    while (token && token->type == TOK__ALIGNAS) {
        int depth = 0;
        saw_alignas = true;
        token = token->next;
        if (!token || token->type != TOK_LPAREN) return false;
        do {
            if (token->type == TOK_LPAREN) {
                ++depth;
            } else if (token->type == TOK_RPAREN) {
                --depth;
            }
            token = token->next;
        } while (token && depth > 0);
        if (depth != 0) return false;
    }
    return saw_alignas && token &&
        (token->type == TOK_CLASS || token->type == TOK_STRUCT ||
         token->type == TOK_UNION);
}

static const char* cxx_method_source_name(CxxMethod* method);
static CxxClass* find_class(const char* qualified_name);
static TypeParam* constructor_parameters_from_method(DeclList* parameters,
                                                     int* parameter_count);
static bool cxx_class_access_context_is_derived_from(
    CxxClass* context, CxxClass* target, CxxClass* access_context,
    unsigned depth);
static bool cxx_nested_class_template_accessible(
    CxxNestedClassTemplate* nested_template, CxxClass* owner,
    CxxClass* access_context);
static void cxx_record_friend_signature_alias_use(
    CxxClass* owner, const char* name,
    CxxClassAliasTemplate* alias_template) {
    for (CxxFriendSignatureAliasUse* use =
             active_friend_signature_alias_uses;
         use; use = use->next) {
        if (use->owner == owner && use->alias_template == alias_template &&
            use->name && name && strcmp(use->name, name) == 0) {
            return;
        }
    }
    CxxFriendSignatureAliasUse* use = ast_arena_alloc(sizeof(*use));
    use->owner = owner;
    use->alias_template = alias_template;
    use->name = name;
    use->next = active_friend_signature_alias_uses;
    active_friend_signature_alias_uses = use;
}

