typedef struct CxxStructuralPointerLocation {
    Decl* declaration;
    int64_t byte_offset;
    int64_t array_start_offset;
    int64_t array_byte_size;
    int64_t array_element_size;
    bool has_subobject_path;
    bool one_past;
    bool array_decay;
    bool has_active_array_path_index;
    size_t active_array_path_index;
    Type* active_array_type;
    CxxStructuralPointerPathElement* subobject_path;
    size_t subobject_path_length;
} CxxStructuralPointerLocation;

static Decl* cxx_structural_pointer_member_identifier_declaration(
    const Expr* expression, bool* namespace_scope_out) {
    Decl* declaration;
    Symbol* symbol;
    bool namespace_scope_target = false;
    CxxNamespace* lookup_namespace;
    if (!expression || expression->kind != EXPR_IDENT ||
        !expression->ident_name) {
        return NULL;
    }
    declaration = expression->ident_decl;
    symbol = g_symtab
        ? symtab_lookup(g_symtab, expression->ident_name) : NULL;
    if (!declaration) declaration = symbol ? symbol->decl : NULL;
    lookup_namespace = active_namespace
        ? active_namespace : g_global_namespace;
    if (lookup_namespace) {
        for (DeclList* item = lookup_namespace->decls; item;
             item = item->next) {
            Decl* candidate = item->decl;
            if (candidate &&
                (candidate->kind == DECL_VAR ||
                 candidate->kind == DECL_FUNC) &&
                ((declaration && candidate == declaration) ||
                 (!declaration && cxx_decl_leaf_matches(
                     candidate->name, expression->ident_name)))) {
                declaration = candidate;
                namespace_scope_target = true;
                break;
            }
        }
    }
    if (active_ast) {
        for (DeclList* item = active_ast->decls; item; item = item->next) {
            Decl* candidate = item->decl;
            if (candidate &&
                (candidate->kind == DECL_VAR ||
                 candidate->kind == DECL_FUNC) &&
                ((declaration && candidate == declaration) ||
                 (!declaration && candidate->name &&
                  strcmp(candidate->name, expression->ident_name) == 0))) {
                declaration = candidate;
                namespace_scope_target = true;
                break;
            }
        }
    }
    if (namespace_scope_out) {
        *namespace_scope_out = namespace_scope_target;
    }
    return declaration;
}

/* Type-trait evaluation may revisit initializer calls after parser scopes have
 * been restored.  Reuse the parser's ordinary scalar overload ranking for
 * calls whose target is unambiguous there, then retain the selected declaration
 * so noexcept analysis observes the actual overload. */
void rcc_parser_cxx_record_call_context(Expr* expression) {
    if (!expression || expression->kind != EXPR_CALL) return;
    expression->cxx_lookup_namespace = active_namespace
        ? active_namespace : g_global_namespace;
}

bool rcc_parser_cxx_bind_resolved_function_call(Expr* expression) {
    Expr* function_expression;
    Decl* selected;
    CxxNamespace* saved_namespace;
    bool is_noexcept = false;
    if (!expression || expression->kind != EXPR_CALL ||
        !expression->call_func ||
        expression->call_func->kind != EXPR_IDENT ||
        !expression->call_func->ident_name) {
        return false;
    }
    function_expression = expression->call_func;
    if (function_expression->ident_decl &&
        function_expression->ident_decl->kind == DECL_FUNC) {
        return false;
    }
    saved_namespace = active_namespace;
    if (expression->cxx_lookup_namespace) {
        active_namespace = expression->cxx_lookup_namespace;
    }
    selected = cxx_template_integer_call_function(expression, NULL);
    active_namespace = saved_namespace;
    if (!selected || selected->func_template_owner ||
        selected->func_is_template_instance || !selected->type ||
        selected->type->kind != TYPE_FUNC || !selected->type->ret_type) {
        return false;
    }
    if (selected->func_noexcept_expr) {
        int64_t value;
        if (!expr_eval_integer_constant(
                selected->func_noexcept_expr, &value)) {
            return false;
        }
        is_noexcept = value != 0;
    } else {
        is_noexcept = selected->func_is_noexcept ||
                      selected->type->function_is_noexcept;
    }
    function_expression->ident_decl = selected;
    function_expression->type = selected->type;
    expression->type = selected->type->ret_type;
    expression->cxx_call_is_noexcept = is_noexcept;
    return true;
}

static bool cxx_structural_pointer_member_declaration_has_static_storage(
    Decl* declaration, bool namespace_scope_target) {
    Symbol* symbol = declaration && declaration->name && g_symtab
        ? symtab_lookup(g_symtab, declaration->name) : NULL;
    if (!declaration) return false;
    if (declaration->kind == DECL_VAR) {
        return (declaration->var_is_global || namespace_scope_target ||
                (symbol && symbol->decl == declaration && symbol->is_global)) &&
            !declaration->var_is_thread_local && !declaration->var_is_vla;
    }
    if (declaration->kind == DECL_FUNC) {
        return declaration->var_is_global || namespace_scope_target ||
            (symbol && symbol->decl == declaration && symbol->is_global);
    }
    return false;
}

/* C++ permits a pointer to a noexcept function to convert to the otherwise
 * identical potentially-throwing function-pointer type. Keep this directed
 * conversion local to structural NTTP evaluation: noexcept remains part of
 * function-type identity everywhere that requires exact compatibility. */
static bool cxx_structural_function_pointer_target_accepts(
    Type* target_function, Type* source_function) {
    Type adjusted_source;
    if (!target_function || !source_function) return false;
    if (type_is_compatible(target_function, source_function)) return true;
    if (target_function->kind != TYPE_FUNC ||
        source_function->kind != TYPE_FUNC ||
        target_function->function_is_noexcept ||
        !source_function->function_is_noexcept) {
        return false;
    }
    adjusted_source = *source_function;
    adjusted_source.function_is_noexcept = false;
    return type_is_compatible(target_function, &adjusted_source);
}

static int cxx_structural_nonvirtual_base_paths(
    Type* derived, Type* target, bool require_public,
    int64_t* adjustment_out, unsigned depth) {
    CxxClass* cls;
    int path_count = 0;
    int64_t first_adjustment = 0;
    if (!derived || !target || depth > 64u) return 0;
    if (derived->cxx_class && target->cxx_class &&
        derived->cxx_class == target->cxx_class) {
        if (adjustment_out) *adjustment_out = 0;
        return 1;
    }
    cls = derived->cxx_class;
    if (!cls || !cls->base_offsets) return 0;
    for (int index = 0; index < cls->base_count; ++index) {
        Type* base_type = cls->bases[index].base
            ? cls->bases[index].base->type : NULL;
        int64_t nested_adjustment = 0;
        int nested_count;
        int64_t total_adjustment;
        if (!base_type || cls->bases[index].is_virtual ||
            cls->base_offsets[index] < 0 ||
            (require_public &&
             cls->bases[index].access != ACCESS_PUBLIC)) {
            continue;
        }
        nested_count = cxx_structural_nonvirtual_base_paths(
            base_type, target, require_public, &nested_adjustment,
            depth + 1u);
        if (nested_count <= 0) continue;
        total_adjustment = (int64_t)cls->base_offsets[index] +
            nested_adjustment;
        if (total_adjustment < 0) continue;
        if (path_count == 0) first_adjustment = total_adjustment;
        path_count += nested_count;
        if (path_count > 1) {
            path_count = 2;
            break;
        }
    }
    if (path_count == 1 && adjustment_out) {
        *adjustment_out = first_adjustment;
    }
    return path_count;
}

static int cxx_structural_virtual_base_paths(
    Type* derived, Type* target, bool require_public,
    int64_t* adjustment_out) {
    CxxClass* cls = derived ? derived->cxx_class : NULL;
    int path_count = 0;
    int64_t first_adjustment = 0;
    if (!cls || !cls->virtual_bases) return 0;
    for (int index = 0; index < cls->virtual_base_count; ++index) {
        CxxVirtualBaseInfo* virtual_base = &cls->virtual_bases[index];
        Type* base_type = virtual_base->base
            ? virtual_base->base->type : NULL;
        int64_t nested_adjustment = 0;
        int nested_count;
        int64_t total_adjustment;
        if (!base_type || virtual_base->offset < 0 ||
            (require_public && !virtual_base->public_path)) {
            continue;
        }
        nested_count = cxx_structural_nonvirtual_base_paths(
            base_type, target, require_public, &nested_adjustment, 0u);
        if (nested_count <= 0) continue;
        total_adjustment = (int64_t)virtual_base->offset +
            nested_adjustment;
        if (total_adjustment < 0) continue;
        if (path_count == 0) first_adjustment = total_adjustment;
        path_count += nested_count;
        if (path_count > 1) {
            path_count = 2;
            break;
        }
    }
    if (path_count == 1 && adjustment_out) {
        *adjustment_out = first_adjustment;
    }
    return path_count;
}

bool rcc_parser_cxx_structural_pointer_conversion(
    Type* source_pointee, Type* target_pointee,
    int64_t* adjustment_out) {
    Type source_unqualified;
    Type target_unqualified;
    int all_paths;
    int public_paths;
    int64_t adjustment = 0;
    int64_t virtual_adjustment = 0;
    if (!source_pointee || !target_pointee ||
        source_pointee->cxx_is_member_pointer ||
        target_pointee->cxx_is_member_pointer ||
        (source_pointee->is_const && !target_pointee->is_const) ||
        (source_pointee->is_volatile && !target_pointee->is_volatile)) {
        return false;
    }
    source_unqualified = *source_pointee;
    target_unqualified = *target_pointee;
    source_unqualified.is_const = false;
    source_unqualified.is_volatile = false;
    target_unqualified.is_const = false;
    target_unqualified.is_volatile = false;
    if (type_is_compatible(&source_unqualified, &target_unqualified)) {
        if (adjustment_out) *adjustment_out = 0;
        return true;
    }
    if (target_unqualified.kind == TYPE_VOID &&
        source_unqualified.kind != TYPE_FUNC) {
        if (adjustment_out) *adjustment_out = 0;
        return true;
    }
    if (source_unqualified.kind != TYPE_STRUCT ||
        target_unqualified.kind != TYPE_STRUCT ||
        !source_unqualified.cxx_class || !target_unqualified.cxx_class) {
        return false;
    }
    all_paths = cxx_structural_nonvirtual_base_paths(
        &source_unqualified, &target_unqualified, false, NULL, 0u) +
        cxx_structural_virtual_base_paths(
            &source_unqualified, &target_unqualified, false, NULL);
    public_paths = cxx_structural_nonvirtual_base_paths(
        &source_unqualified, &target_unqualified, true, &adjustment, 0u) +
        cxx_structural_virtual_base_paths(
            &source_unqualified, &target_unqualified, true,
            &virtual_adjustment);
    if (all_paths != 1 || public_paths != 1) return false;
    if (adjustment_out) {
        *adjustment_out = adjustment != 0 || virtual_adjustment == 0
            ? adjustment : virtual_adjustment;
    }
    return true;
}

static Decl* cxx_structural_pointer_member_address_declaration(
    const Expr* expression, Type* pointer_type,
    int64_t* pointer_adjustment_out) {
    const Expr* operand;
    Decl* declaration;
    bool namespace_scope_target = false;
    if (!expression || expression->kind != EXPR_ADDR ||
        !(operand = expression->unary_operand) ||
        operand->kind != EXPR_IDENT || !operand->ident_name) {
        return NULL;
    }
    declaration = cxx_structural_pointer_member_identifier_declaration(
        operand, &namespace_scope_target);
    if (!declaration || !declaration->type || !pointer_type ||
        pointer_type->kind != TYPE_PTR ||
        !decl_link_name(declaration)) {
        return NULL;
    }
    if (pointer_type->base && pointer_type->base->kind == TYPE_FUNC) {
        if (!cxx_structural_function_pointer_target_accepts(
                pointer_type->base, declaration->type)) {
            return NULL;
        }
        if (pointer_adjustment_out) *pointer_adjustment_out = 0;
    } else if (!rcc_parser_cxx_structural_pointer_conversion(
                   declaration->type, pointer_type->base,
                   pointer_adjustment_out)) {
        return NULL;
    }
    if (!cxx_structural_pointer_member_declaration_has_static_storage(
            declaration, namespace_scope_target)) {
        return NULL;
    }
    return declaration;
}

static TypeField* cxx_structural_pointer_member_field(
    Type* owner_type, const Expr* expression) {
    TypeField* match = NULL;
    if (!owner_type || !expression || !expression->member_name ||
        (owner_type->kind != TYPE_STRUCT &&
         owner_type->kind != TYPE_UNION)) {
        return NULL;
    }
    if (expression->member_field && expression->member_field->name &&
        strcmp(expression->member_field->name,
               expression->member_name) == 0) {
        for (TypeField* field = owner_type->fields; field; field = field->next) {
            if (field == expression->member_field) return field;
        }
    }
    for (TypeField* field = owner_type->fields; field; field = field->next) {
        if (!field->name ||
            strcmp(field->name, expression->member_name) != 0) {
            continue;
        }
        if (match) return NULL;
        match = field;
    }
    return match;
}

static bool cxx_structural_pointer_member_path_location(
    const Expr* expression, Type* pointer_type, bool decay_array,
    CxxStructuralPointerLocation* location) {
    const Expr* current;
    const Expr** steps = NULL;
    Decl* declaration;
    Type* current_type;
    bool namespace_scope_target = false;
    bool function_reference = false;
    size_t step_count = 0u;
    size_t path_position = 0u;
    int64_t offset = 0;
    if (!expression || !pointer_type || pointer_type->kind != TYPE_PTR ||
        !pointer_type->base || !location) {
        return false;
    }
    for (current = expression;
         current && (current->kind == EXPR_MEMBER ||
                     current->kind == EXPR_INDEX);
         current = current->kind == EXPR_MEMBER
             ? current->member_base : current->index_base) {
        if (step_count == SIZE_MAX / sizeof(*steps)) return false;
        ++step_count;
    }
    if (!current || current->kind != EXPR_IDENT || !current->ident_name ||
        step_count > SIZE_MAX / sizeof(*steps) ||
        step_count > SIZE_MAX / sizeof(*location->subobject_path)) {
        return false;
    }
    if (step_count != 0u) {
        steps = ast_arena_alloc(step_count * sizeof(*steps));
        if (!steps) return false;
    }
    current = expression;
    for (size_t index = 0u; index < step_count; ++index) {
        steps[index] = current;
        current = current->kind == EXPR_MEMBER
            ? current->member_base : current->index_base;
    }
    declaration = cxx_structural_pointer_member_identifier_declaration(
        current, &namespace_scope_target);
    function_reference = pointer_type->is_reference && pointer_type->base &&
        pointer_type->base->kind == TYPE_FUNC && declaration &&
        declaration->kind == DECL_FUNC && step_count == 0u;
    if (!declaration ||
        (declaration->kind != DECL_VAR && !function_reference) ||
        !declaration->type || !decl_link_name(declaration) ||
        !cxx_structural_pointer_member_declaration_has_static_storage(
            declaration, namespace_scope_target)) {
        return false;
    }
    current_type = declaration->type;
    memset(location, 0, sizeof(*location));
    if (step_count != 0u) {
        location->subobject_path = ast_arena_alloc(
            step_count * sizeof(*location->subobject_path));
        if (!location->subobject_path) return false;
    }
    for (size_t remaining = step_count; remaining > 0u; --remaining) {
        const Expr* step = steps[remaining - 1u];
        if (step->kind == EXPR_MEMBER) {
            TypeField* field = cxx_structural_pointer_member_field(
                current_type, step);
            if (!field || field->is_bitfield || field->offset < 0 ||
                !field->type || field->type->size <= 0 ||
                current_type->size <= 0 ||
                field->offset > current_type->size ||
                field->type->size > current_type->size - field->offset ||
                offset > INT64_MAX - field->offset) {
                return false;
            }
            location->subobject_path[path_position++] =
                (CxxStructuralPointerPathElement){
                    CXX_STRUCTURAL_POINTER_PATH_MEMBER, 0,
                    current_type, field};
            offset += field->offset;
            current_type = field->type;
            location->array_start_offset = 0;
            location->array_byte_size = 0;
            location->array_element_size = 0;
            location->has_active_array_path_index = false;
            location->active_array_type = NULL;
            location->array_decay = false;
            location->one_past = false;
            continue;
        }
        if (step->kind == EXPR_INDEX) {
            int64_t index;
            int64_t element_size;
            int64_t array_byte_size;
            bool final_step = step == expression;
            if (!current_type || current_type->kind != TYPE_ARRAY ||
                current_type->array_len <= 0 || !current_type->base ||
                current_type->base->size <= 0 || !step->index_expr ||
                !expr_eval_integer_constant(step->index_expr, &index) ||
                index < 0 || index > current_type->array_len ||
                (index == current_type->array_len &&
                 (!final_step || decay_array))) {
                return false;
            }
            element_size = current_type->base->size;
            if ((int64_t)current_type->array_len >
                    INT64_MAX / element_size ||
                index > INT64_MAX / element_size ||
                offset > INT64_MAX - index * element_size) {
                return false;
            }
            array_byte_size =
                (int64_t)current_type->array_len * element_size;
            location->array_start_offset = offset;
            location->array_byte_size = array_byte_size;
            location->array_element_size = element_size;
            location->has_active_array_path_index = true;
            location->active_array_path_index = path_position;
            location->active_array_type = current_type;
            location->array_decay = false;
            offset += index * element_size;
            location->subobject_path[path_position++] =
                (CxxStructuralPointerPathElement){
                    CXX_STRUCTURAL_POINTER_PATH_ARRAY_INDEX, index,
                    current_type, NULL};
            location->one_past = final_step &&
                index == current_type->array_len;
            current_type = current_type->base;
            continue;
        }
        return false;
    }
    if (decay_array) {
        if (!current_type || current_type->kind != TYPE_ARRAY ||
            current_type->array_len <= 0 || !current_type->base ||
            !type_is_compatible(pointer_type->base, current_type->base) ||
            current_type->base->size <= 0 ||
            (int64_t)current_type->array_len >
                INT64_MAX / current_type->base->size) {
            return false;
        }
        location->array_start_offset = offset;
        location->array_element_size = current_type->base->size;
        location->array_byte_size =
            (int64_t)current_type->array_len * current_type->base->size;
        location->has_active_array_path_index = false;
        location->active_array_type = current_type;
        location->array_decay = true;
        location->one_past = false;
    } else if (!type_is_compatible(pointer_type->base, current_type) ||
               (pointer_type->base->kind != TYPE_FUNC &&
                pointer_type->base->size <= 0) ||
               (pointer_type->base->kind == TYPE_FUNC &&
                !function_reference)) {
        return false;
    }
    if (location->array_byte_size > 0 &&
        (location->array_start_offset < 0 ||
         location->array_start_offset >
             INT64_MAX - location->array_byte_size ||
         offset < location->array_start_offset ||
         offset > location->array_start_offset +
             location->array_byte_size)) {
        return false;
    }
    location->declaration = declaration;
    location->byte_offset = offset;
    location->has_subobject_path = path_position != 0u || decay_array;
    location->subobject_path_length = path_position;
    if (!location->has_subobject_path && !pointer_type->is_reference) {
        return false;
    }
    return true;
}

static bool cxx_structural_pointer_member_indexed_location(
    const Expr* indexed_expression, Type* pointer_type, bool decay_array,
    CxxStructuralPointerLocation* location) {
    return cxx_structural_pointer_member_path_location(
        indexed_expression, pointer_type, decay_array, location);
}

static bool cxx_structural_pointer_member_location(
    const Expr* expression, Type* pointer_type,
    CxxStructuralPointerLocation* location) {
    if (!expression || !pointer_type || pointer_type->kind != TYPE_PTR ||
        !pointer_type->base || !location) {
        return false;
    }
    if (expression->kind == EXPR_COND) {
        int64_t condition;
        if (!expr_eval_integer_constant(expression->cond_test, &condition)) {
            return false;
        }
        return cxx_structural_pointer_member_location(
            condition ? expression->cond_then : expression->cond_else,
            pointer_type, location);
    }
    if (expression->kind == EXPR_CAST && expression->cast_expr &&
        expression->cast_type && expression->cast_type->kind == TYPE_PTR &&
        type_is_compatible(expression->cast_type, pointer_type)) {
        Type* source_type = expression->cast_expr->type;
        int64_t base_adjustment = 0;
        bool explicit_pointer_cast =
            expression->cxx_cast_kind == CXX_CAST_STATIC ||
            expression->cxx_cast_kind == CXX_CAST_CONST;
        bool array_to_pointer_decay =
            expression->cxx_cast_kind == CXX_CAST_NONE && source_type &&
            source_type->kind == TYPE_ARRAY && source_type->base &&
            expression->cast_type->base &&
            type_is_compatible(source_type->base,
                               expression->cast_type->base);
        if (source_type && source_type->kind == TYPE_PTR &&
            source_type->base && pointer_type->base &&
            rcc_parser_cxx_structural_pointer_conversion(
                source_type->base, pointer_type->base, &base_adjustment)) {
            CxxStructuralPointerLocation source_location;
            if (cxx_structural_pointer_member_location(
                    expression->cast_expr, source_type,
                    &source_location) &&
                source_location.declaration &&
                !source_location.has_subobject_path &&
                !source_location.one_past &&
                source_location.byte_offset <=
                    INT64_MAX - base_adjustment) {
                *location = source_location;
                location->byte_offset += base_adjustment;
                return true;
            }
        }
        if (explicit_pointer_cast || array_to_pointer_decay) {
            return cxx_structural_pointer_member_location(
                expression->cast_expr, pointer_type, location);
        }
    }
    if (pointer_type->is_reference &&
        (expression->kind == EXPR_IDENT ||
         expression->kind == EXPR_INDEX ||
         expression->kind == EXPR_MEMBER) &&
        cxx_structural_pointer_member_indexed_location(
            expression, pointer_type, false, location)) {
        return true;
    }
    if ((expression->kind == EXPR_IDENT ||
         expression->kind == EXPR_INDEX ||
         expression->kind == EXPR_MEMBER) &&
        cxx_structural_pointer_member_indexed_location(
            expression, pointer_type, true, location)) {
        return true;
    }
    if (expression->kind == EXPR_ADDR && expression->unary_operand &&
        (expression->unary_operand->kind == EXPR_INDEX ||
         expression->unary_operand->kind == EXPR_MEMBER)) {
        return cxx_structural_pointer_member_indexed_location(
            expression->unary_operand, pointer_type, false, location);
    }
    if (expression->kind == EXPR_ADD || expression->kind == EXPR_SUB) {
        const Expr* pointer_expression = expression->binary_lhs;
        const Expr* integer_expression = expression->binary_rhs;
        int64_t element_offset;
        CxxStructuralPointerLocation base_location;
        Type* object_type;
        int64_t element_size;
        int64_t object_bytes;
        int64_t byte_delta;
        int64_t new_offset;
        int64_t relative_offset;
        int64_t relative_new_offset;
        CxxStructuralPointerPathElement* updated_path = NULL;
        if (expression->kind == EXPR_ADD && pointer_expression &&
            expr_eval_integer_constant(
                (Expr*)pointer_expression, &element_offset)) {
            const Expr* temporary = pointer_expression;
            pointer_expression = integer_expression;
            integer_expression = temporary;
        }
        if (!integer_expression ||
            !expr_eval_integer_constant(
                (Expr*)integer_expression, &element_offset) ||
            !cxx_structural_pointer_member_location(
                pointer_expression, pointer_type, &base_location) ||
            !base_location.declaration ||
            !(object_type = base_location.declaration->type)) {
            return false;
        }
        if (base_location.has_subobject_path) {
            if (base_location.array_element_size <= 0 ||
                base_location.array_byte_size <= 0 ||
                !base_location.active_array_type ||
                (base_location.array_decay &&
                 (base_location.has_active_array_path_index ||
                  base_location.active_array_path_index != 0u)) ||
                (!base_location.array_decay &&
                 (!base_location.has_active_array_path_index ||
                  !base_location.subobject_path ||
                  base_location.active_array_path_index >=
                      base_location.subobject_path_length ||
                  base_location.subobject_path[
                      base_location.active_array_path_index].kind !=
                      CXX_STRUCTURAL_POINTER_PATH_ARRAY_INDEX)) ||
                !pointer_type->base ||
                pointer_type->base->size !=
                    base_location.array_element_size ||
                base_location.array_start_offset < 0 ||
                base_location.array_start_offset >
                    INT64_MAX - base_location.array_byte_size ||
                base_location.byte_offset <
                    base_location.array_start_offset ||
                base_location.byte_offset >
                    base_location.array_start_offset +
                        base_location.array_byte_size) {
                return false;
            }
            element_size = base_location.array_element_size;
            object_bytes = base_location.array_byte_size;
            relative_offset = base_location.byte_offset -
                base_location.array_start_offset;
        } else {
            if (object_type->size <= 0 || !pointer_type->base ||
                pointer_type->base->size <= 0 ||
                !type_is_compatible(pointer_type->base, object_type) ||
                pointer_type->base->size != object_type->size) {
                return false;
            }
            element_size = pointer_type->base->size;
            object_bytes = object_type->size;
            relative_offset = base_location.byte_offset;
        }
        if (expression->kind == EXPR_SUB) {
            if (element_offset == INT64_MIN) return false;
            element_offset = -element_offset;
        }
        if (element_offset > INT64_MAX / element_size ||
            element_offset < INT64_MIN / element_size) {
            return false;
        }
        byte_delta = element_offset * element_size;
        if ((byte_delta > 0 && relative_offset >
                INT64_MAX - byte_delta) ||
            (byte_delta < 0 && relative_offset <
                INT64_MIN - byte_delta)) {
            return false;
        }
        relative_new_offset = relative_offset + byte_delta;
        if (relative_new_offset < 0 ||
            relative_new_offset > object_bytes ||
            base_location.array_start_offset >
                INT64_MAX - relative_new_offset) {
            return false;
        }
        new_offset = base_location.array_start_offset +
            relative_new_offset;
        *location = base_location;
        location->byte_offset = new_offset;
        location->one_past = relative_new_offset == object_bytes;
        if (location->has_subobject_path) {
            size_t new_path_length = location->subobject_path_length;
            size_t decay_parent_path_index = SIZE_MAX;
            bool decay_to_next_array_element = false;
            if (location->array_decay && relative_new_offset == object_bytes &&
                location->subobject_path_length != 0u &&
                location->subobject_path) {
                size_t parent_index = location->subobject_path_length - 1u;
                const CxxStructuralPointerPathElement* parent_path =
                    &location->subobject_path[parent_index];
                Type* parent_array_type =
                    (Type*)parent_path->owner_type;
                if (parent_path->kind ==
                        CXX_STRUCTURAL_POINTER_PATH_ARRAY_INDEX &&
                    parent_array_type &&
                    parent_array_type->kind == TYPE_ARRAY &&
                    parent_array_type->base &&
                    parent_path->array_index < parent_array_type->array_len &&
                    type_is_compatible(
                        parent_array_type->base,
                        base_location.active_array_type)) {
                    decay_parent_path_index = parent_index;
                    decay_to_next_array_element = true;
                }
            }
            if (location->array_decay && relative_new_offset != 0 &&
                !decay_to_next_array_element) {
                if (new_path_length == SIZE_MAX ||
                    new_path_length + 1u >
                        SIZE_MAX / sizeof(*updated_path)) {
                    return false;
                }
                ++new_path_length;
            }
            if (new_path_length != 0u) {
                updated_path = ast_arena_alloc(
                    new_path_length * sizeof(*updated_path));
                if (!updated_path) return false;
                if (location->subobject_path_length != 0u) {
                    memcpy(updated_path, location->subobject_path,
                           location->subobject_path_length *
                               sizeof(*updated_path));
                }
            }
            if (location->array_decay) {
                if (decay_to_next_array_element) {
                    CxxStructuralPointerPathElement* parent_path =
                        &updated_path[decay_parent_path_index];
                    Type* parent_array_type =
                        (Type*)parent_path->owner_type;
                    ++parent_path->array_index;
                    location->one_past = parent_path->array_index ==
                        parent_array_type->array_len;
                    location->array_start_offset = new_offset;
                    if (location->one_past) {
                        location->array_byte_size = 0;
                    }
                } else if (relative_new_offset != 0) {
                    updated_path[location->subobject_path_length] =
                        (CxxStructuralPointerPathElement){
                            CXX_STRUCTURAL_POINTER_PATH_ARRAY_INDEX,
                            relative_new_offset / element_size,
                            location->active_array_type, NULL};
                    location->active_array_path_index =
                        location->subobject_path_length;
                    location->has_active_array_path_index = true;
                    location->array_decay = false;
                }
            } else {
                updated_path[location->active_array_path_index].array_index =
                    relative_new_offset / element_size;
            }
            location->subobject_path = updated_path;
            location->subobject_path_length = new_path_length;
        }
        return true;
    }
    if (expression->kind == EXPR_ADDR) {
        int64_t pointer_adjustment = 0;
        Decl* declaration = cxx_structural_pointer_member_address_declaration(
            expression, pointer_type, &pointer_adjustment);
        if (!declaration) return false;
        location->declaration = declaration;
        location->byte_offset = pointer_adjustment;
        location->array_start_offset = 0;
        location->array_byte_size = 0;
        location->array_element_size = 0;
        location->has_subobject_path = false;
        location->one_past = false;
        location->array_decay = false;
        location->has_active_array_path_index = false;
        location->active_array_path_index = 0u;
        location->active_array_type = NULL;
        location->subobject_path = NULL;
        location->subobject_path_length = 0u;
        return true;
    }
    return false;
}

static bool cxx_structural_pointer_member_value(
    const Expr* expression, Type* pointer_type, int64_t* value_out) {
    CxxStructuralPointerLocation location;
    int64_t offset;
    if (!expression || !pointer_type || pointer_type->kind != TYPE_PTR ||
        !value_out) {
        return false;
    }
    if (expression->kind == EXPR_COND) {
        int64_t condition;
        if (!expr_eval_integer_constant(expression->cond_test, &condition)) {
            return false;
        }
        return cxx_structural_pointer_member_value(
            condition ? expression->cond_then : expression->cond_else,
            pointer_type, value_out);
    }
    if (pointer_type->cxx_is_member_pointer &&
        expression->kind == EXPR_CAST && expression->unary_operand &&
        expression->type &&
        type_is_compatible(pointer_type, expression->type)) {
        return cxx_structural_pointer_member_value(
            expression->unary_operand, pointer_type, value_out);
    }
    if (pointer_type->is_reference) {
        if (!cxx_structural_pointer_member_location(
                expression, pointer_type, &location) ||
            !location.declaration) {
            return false;
        }
        return cxx_structural_pointer_value_register(
            location.declaration, location.byte_offset,
            location.has_subobject_path, location.one_past,
            location.array_decay, location.subobject_path,
            location.subobject_path_length, value_out);
    }
    if (pointer_type->cxx_is_member_pointer) {
        CxxClass* owner = pointer_type->cxx_member_pointer_owner
            ? pointer_type->cxx_member_pointer_owner->cxx_class : NULL;
        CxxClass* declaring_owner =
            expression->cxx_member_pointer_form_declaring_class;
        TypeMethod* method = expression->cxx_member_function_pointer_method;
        const char* member_name = expression->cxx_member_pointer_form_name;
        int64_t owner_adjustment = 0;
        int64_t member_offset = expression->int_val;
        if ((!expression->cxx_member_pointer_form &&
             cxx_expr_is_nullptr_constant(expression)) ||
            (expr_eval_integer_constant((Expr*)expression, &offset) &&
             offset == 0 && !expression->cxx_member_pointer_form)) {
            *value_out = -1;
            return true;
        }
        if (!member_name && method) member_name = method->name;
        if (!declaring_owner && method && method->function_decl &&
            method->function_decl->func_method_owner) {
            declaring_owner = method->function_decl->func_method_owner
                                  ->cxx_class;
        }
        if (!declaring_owner && expression->type &&
            expression->type->cxx_member_pointer_owner) {
            declaring_owner = expression->type->cxx_member_pointer_owner
                                  ->cxx_class;
        }
        if (!expression->cxx_member_pointer_form ||
            expression->cxx_member_pointer_form_deferred ||
            expression->cxx_member_pointer_form_overload_set || !owner ||
            !declaring_owner || !member_name) {
            return false;
        }
        if (declaring_owner != owner) {
            if (!owner->type || !declaring_owner->type) return false;
            int paths = cxx_structural_nonvirtual_base_paths(
                owner->type, declaring_owner->type, true,
                &owner_adjustment, 0u);
            if (paths != 1) return false;
        }
        if (method) {
            member_offset = owner_adjustment;
        } else if ((owner_adjustment > 0 &&
                    member_offset > INT64_MAX - owner_adjustment) ||
                   (owner_adjustment < 0 &&
                    member_offset < INT64_MIN - owner_adjustment)) {
            return false;
        } else {
            member_offset += owner_adjustment;
        }
        return cxx_structural_member_pointer_value_register(
            declaring_owner, member_name, method, member_offset, value_out);
    }
    if (cxx_expr_is_nullptr_constant(expression) ||
        (expr_eval_integer_constant((Expr*)expression, &offset) &&
         offset == 0)) {
        *value_out = 0;
        return true;
    }
    if (expression->kind == EXPR_ADD || expression->kind == EXPR_SUB) {
        const Expr* lhs = expression->binary_lhs;
        const Expr* rhs = expression->binary_rhs;
        if (!pointer_type->base || pointer_type->base->kind == TYPE_FUNC) {
            return false;
        }
        if (rhs && expr_eval_integer_constant((Expr*)rhs, &offset) &&
            offset == 0) {
            if (cxx_structural_pointer_member_value(
                    lhs, pointer_type, value_out)) return true;
        }
        if (expression->kind == EXPR_ADD && lhs &&
            expr_eval_integer_constant((Expr*)lhs, &offset) && offset == 0) {
            if (cxx_structural_pointer_member_value(
                    rhs, pointer_type, value_out)) return true;
        }
    }
    if (!cxx_structural_pointer_member_location(
            expression, pointer_type, &location) ||
        !location.declaration) {
        return false;
    }
    return cxx_structural_pointer_value_register(
        location.declaration, location.byte_offset,
        location.has_subobject_path, location.one_past,
        location.array_decay, location.subobject_path,
        location.subobject_path_length, value_out);
}

static bool cxx_structural_select_function_template_pointer(
    Expr* expression, Type* pointer_type) {
    Expr* name = expression;
    Decl* selected = NULL;
    Decl* ordinary_selected = NULL;
    bool has_templates = false;
    bool template_ambiguous = false;
    bool ordinary_ambiguous = false;
    int template_rank = -1;
    int ordinary_rank = -1;
    if (name && name->kind == EXPR_ADDR) name = name->unary_operand;
    if (!rcc_parser_is_cxx_mode() || !name ||
        name->kind != EXPR_IDENT || !name->ident_name || !pointer_type ||
        pointer_type->kind != TYPE_PTR ||
        pointer_type->cxx_is_member_pointer || !pointer_type->base ||
        pointer_type->base->kind != TYPE_FUNC) {
        return false;
    }
    selected = rcc_parser_cxx_resolve_function_pointer_template(
        name->ident_name, active_namespace, pointer_type, &has_templates,
        &template_ambiguous, &template_rank);
    if (!has_templates) return false;
    ordinary_rank = cxx_parser_function_pointer_best_declaration(
        expression, pointer_type, &ordinary_selected,
        &ordinary_ambiguous);
    if (ordinary_rank >= 0 &&
        (!selected || ordinary_rank <= template_rank)) {
        if (!ordinary_ambiguous && ordinary_selected) {
            name->ident_decl = ordinary_selected;
            name->type = ordinary_selected->type;
        }
        return false;
    }
    if (!selected || template_ambiguous || template_rank < 0 ||
        ordinary_ambiguous) {
        return false;
    }
    name->ident_decl = selected;
    name->type = selected->type;
    if (active_ast && selected->func_is_template_instance) {
        bool present = false;
        for (DeclList* item = active_ast->decls; item; item = item->next) {
            if (item->decl == selected) {
                present = true;
                break;
            }
        }
        if (!present) ast_add_decl(active_ast, selected);
    }
    return true;
}

static bool cxx_structural_class_collect_member_values(
    Type* type, ExprList* initializer, bool value_init,
    int64_t* member_values, size_t member_capacity, int* member_count);

static bool cxx_structural_array_collect_scalar_values(
    Type* array_type, Expr* initializer, int64_t* member_values,
    size_t member_capacity, int* member_count) {
    ExprList* item = NULL;
    Type* element_type;
    Type* initializer_type = NULL;
    if (!array_type || array_type->kind != TYPE_ARRAY ||
        !array_type->base || array_type->array_len <= 0 ||
        array_type->array_bound) {
        return false;
    }
    element_type = array_type->base;
    if (initializer) {
        if (initializer->kind != EXPR_COMPOUND) return false;
        initializer_type = initializer->compound_type
            ? initializer->compound_type : initializer->type;
        if (initializer_type &&
            !type_is_compatible(array_type, initializer_type)) {
            return false;
        }
        item = initializer->compound_init;
    }
    if (element_type->kind == TYPE_ARRAY) {
        if (element_type->array_len <= 0 || element_type->array_bound) {
            return false;
        }
    } else if (element_type->kind == TYPE_STRUCT) {
        if (!cxx_structural_class_value_supported_subset(element_type)) {
            return false;
        }
    } else if ((!type_is_integer(element_type) &&
                element_type->kind != TYPE_ENUM &&
                element_type->kind != TYPE_FLOAT &&
                element_type->kind != TYPE_DOUBLE &&
                element_type->kind != TYPE_PTR &&
                element_type->kind != TYPE_NULLPTR) ||
               (element_type->kind == TYPE_FLOAT &&
                element_type->size != 4) ||
               (element_type->kind == TYPE_DOUBLE &&
                element_type->size != 8) ||
               (element_type->kind != TYPE_PTR &&
                element_type->kind != TYPE_NULLPTR &&
                element_type->size <= 0) ||
               (element_type->kind != TYPE_PTR &&
                element_type->kind != TYPE_NULLPTR &&
                element_type->size > 8)) {
        return false;
    }
    for (int index = 0; index < array_type->array_len; ++index) {
        Expr* element_initializer = NULL;
        if (item) {
            if (item->designator_kind != INIT_DESIGNATOR_NONE || !item->expr) {
                return false;
            }
            element_initializer = item->expr;
            item = item->next;
        }
        if (element_type->kind == TYPE_ARRAY) {
            if (!cxx_structural_array_collect_scalar_values(
                    element_type, element_initializer, member_values,
                    member_capacity, member_count)) {
                return false;
            }
            continue;
        }
        if (element_type->kind == TYPE_STRUCT) {
            ExprList* nested_initializer = NULL;
            Type* nested_type = NULL;
            if (element_initializer) {
                if (element_initializer->kind != EXPR_COMPOUND) {
                    return false;
                }
                nested_type = element_initializer->compound_type
                    ? element_initializer->compound_type
                    : element_initializer->type;
                if (nested_type &&
                    !type_is_compatible(element_type, nested_type)) {
                    return false;
                }
                nested_initializer = element_initializer->compound_init;
            }
            if (!cxx_structural_class_collect_member_values(
                    element_type, nested_initializer,
                    !element_initializer ||
                        element_initializer->compound_value_init,
                    member_values, member_capacity, member_count)) {
                return false;
            }
            continue;
        }
        int64_t value = 0;
        if (element_initializer &&
            element_type->kind == TYPE_NULLPTR) {
            if (!cxx_expr_is_nullptr_constant(element_initializer)) {
                return false;
            }
        } else if (element_initializer && element_type->kind == TYPE_PTR) {
            int64_t null_pointer_constant;
            if (element_type->cxx_is_member_pointer) {
                if (!cxx_structural_pointer_member_value(
                        element_initializer, element_type, &value)) {
                    return false;
                }
            } else if (cxx_expr_is_nullptr_constant(element_initializer)) {
                value = 0;
            } else if (expr_eval_integer_constant(
                           element_initializer, &null_pointer_constant)) {
                if (null_pointer_constant != 0) return false;
                value = 0;
            } else if (!cxx_structural_pointer_member_value(
                           element_initializer, element_type, &value)) {
                return false;
            }
        } else if (element_initializer && type_is_floating(element_type)) {
            double floating_value;
            if (!eval_template_floating_expression(
                    element_initializer, NULL, NULL, NULL, &floating_value)) {
                return false;
            }
            if (!cxx_structural_floating_member_conversion_is_valid(
                    element_initializer, element_type, floating_value)) {
                rcc_error(element_initializer->loc,
                          "narrowing conversion in structural class non-type template argument");
                return false;
            }
            if (element_type->kind == TYPE_FLOAT) {
                float narrowed = (float)floating_value;
                uint32_t bits;
                if (element_type->size != (int)sizeof(narrowed)) return false;
                memcpy(&bits, &narrowed, sizeof(bits));
                value = (int64_t)bits;
            } else {
                uint64_t bits;
                if (element_type->size != (int)sizeof(floating_value)) {
                    return false;
                }
                memcpy(&bits, &floating_value, sizeof(bits));
                memcpy(&value, &bits, sizeof(value));
            }
        } else if (element_initializer &&
                   !expr_eval_integer_constant(element_initializer, &value)) {
            return false;
        }
        if (*member_count < 0 ||
            (size_t)*member_count >= member_capacity || !member_values) {
            return false;
        }
        member_values[(*member_count)++] = value;
    }
    return item == NULL;
}

static bool cxx_structural_class_collect_member_values(
    Type* type, ExprList* initializer, bool value_init,
    int64_t* member_values, size_t member_capacity, int* member_count) {
    TypeParam* field;
    bool has_nonstatic_field = false;
    for (field = type->cxx_class->fields; field; field = field->next) {
        if (!field->is_static) {
            has_nonstatic_field = true;
            break;
        }
    }
    if (!has_nonstatic_field) {
        int64_t empty_value;
        return !initializer ||
            (value_init && !initializer->next &&
             initializer->designator_kind == INIT_DESIGNATOR_NONE &&
             initializer->expr &&
             expr_eval_integer_constant(initializer->expr, &empty_value) &&
             empty_value == 0);
    }
    for (field = type->cxx_class->fields; field; field = field->next) {
        Expr* field_initializer = NULL;
        int64_t member_value = 0;
        if (field->is_static) continue;
        if (initializer) {
            if (initializer->designator_kind != INIT_DESIGNATOR_NONE ||
                !initializer->expr) {
                return false;
            }
            field_initializer = initializer->expr;
            initializer = initializer->next;
        } else {
            field_initializer = field->initializer;
        }
        if (field_initializer && field->type->kind == TYPE_PTR &&
            !field->type->cxx_is_member_pointer && field->type->base &&
            field->type->base->kind == TYPE_FUNC) {
            (void)cxx_structural_select_function_template_pointer(
                field_initializer, field->type);
        }
        if (field->type->kind == TYPE_PTR && field->type->is_reference &&
            !field_initializer) {
            return false;
        }
        if (field->type->kind == TYPE_ARRAY) {
            if (field->type->base &&
                field->type->base->kind == TYPE_ARRAY) {
                if (!cxx_structural_array_collect_scalar_values(
                        field->type, field_initializer, member_values,
                        member_capacity, member_count)) {
                    return false;
                }
                continue;
            }
            ExprList* array_initializer = NULL;
            Type* initializer_type = NULL;
            Type* element_type = field->type->base;
            if (!element_type || field->type->array_len <= 0 ||
                field->type->array_bound) {
                return false;
            }
            if (element_type->kind == TYPE_STRUCT) {
                if (!cxx_structural_class_value_supported_subset(
                        element_type)) {
                    return false;
                }
            } else if (((!type_is_integer(element_type) &&
                         element_type->kind != TYPE_ENUM &&
                         element_type->kind != TYPE_PTR &&
                         element_type->kind != TYPE_NULLPTR) &&
                        element_type->kind != TYPE_FLOAT &&
                        element_type->kind != TYPE_DOUBLE) ||
                       (element_type->kind == TYPE_FLOAT &&
                        element_type->size != 4) ||
                       (element_type->kind == TYPE_DOUBLE &&
                        element_type->size != 8) ||
                       (element_type->kind != TYPE_PTR &&
                        element_type->kind != TYPE_NULLPTR &&
                        element_type->size <= 0) ||
                       (element_type->kind != TYPE_PTR &&
                        element_type->kind != TYPE_NULLPTR &&
                        element_type->size > 8)) {
                return false;
            }
            if (field_initializer) {
                if (field_initializer->kind != EXPR_COMPOUND) return false;
                initializer_type = field_initializer->compound_type
                    ? field_initializer->compound_type
                    : field_initializer->type;
                if (initializer_type &&
                    !type_is_compatible(field->type, initializer_type)) {
                    return false;
                }
                array_initializer = field_initializer->compound_init;
            }
            for (int element_index = 0;
                 element_index < field->type->array_len; ++element_index) {
                int64_t element_value = 0;
                Expr* element_initializer = NULL;
                if (array_initializer) {
                    element_initializer = array_initializer->expr;
                    if (array_initializer->designator_kind !=
                            INIT_DESIGNATOR_NONE || !element_initializer) {
                        return false;
                    }
                    array_initializer = array_initializer->next;
                }
                if (element_type->kind == TYPE_STRUCT) {
                    ExprList* nested_initializer = NULL;
                    Type* nested_type = NULL;
                    if (element_initializer) {
                        if (element_initializer->kind != EXPR_COMPOUND) {
                            return false;
                        }
                        nested_type = element_initializer->compound_type
                            ? element_initializer->compound_type
                            : element_initializer->type;
                        if (nested_type &&
                            !type_is_compatible(element_type, nested_type)) {
                            return false;
                        }
                        nested_initializer =
                            element_initializer->compound_init;
                    }
                    if (!cxx_structural_class_collect_member_values(
                            element_type, nested_initializer,
                            !element_initializer ||
                                element_initializer->compound_value_init,
                            member_values, member_capacity, member_count)) {
                        return false;
                    }
                } else {
                    if (element_initializer &&
                        element_type->kind == TYPE_NULLPTR) {
                        if (!cxx_expr_is_nullptr_constant(
                                element_initializer)) {
                            return false;
                        }
                    } else if (element_initializer &&
                        element_type->kind == TYPE_PTR) {
                        int64_t null_pointer_constant;
                        if (element_type->cxx_is_member_pointer) {
                            if (!cxx_structural_pointer_member_value(
                                    element_initializer, element_type,
                                    &element_value)) {
                                return false;
                            }
                        } else if (cxx_expr_is_nullptr_constant(
                                element_initializer)) {
                            element_value = 0;
                        } else if (expr_eval_integer_constant(
                                       element_initializer,
                                       &null_pointer_constant)) {
                            if (null_pointer_constant != 0) return false;
                            element_value = 0;
                        } else if (!cxx_structural_pointer_member_value(
                                       element_initializer, element_type,
                                       &element_value)) {
                            return false;
                        }
                    } else if (element_initializer &&
                        type_is_floating(element_type)) {
                        double floating_value;
                        if (!eval_template_floating_expression(
                                element_initializer, NULL, NULL, NULL,
                                &floating_value)) {
                            return false;
                        }
                        if (!cxx_structural_floating_member_conversion_is_valid(
                                element_initializer, element_type,
                                floating_value)) {
                            rcc_error(element_initializer->loc,
                                      "narrowing conversion in structural class non-type template argument");
                            return false;
                        }
                        if (element_type->kind == TYPE_FLOAT) {
                            float narrowed = (float)floating_value;
                            uint32_t bits;
                            if (element_type->size != (int)sizeof(narrowed)) {
                                return false;
                            }
                            memcpy(&bits, &narrowed, sizeof(bits));
                            element_value = (int64_t)bits;
                        } else {
                            uint64_t bits;
                            if (element_type->size !=
                                (int)sizeof(floating_value)) {
                                return false;
                            }
                            memcpy(&bits, &floating_value, sizeof(bits));
                            memcpy(&element_value, &bits,
                                   sizeof(element_value));
                        }
                    } else if (element_initializer &&
                               !expr_eval_integer_constant(
                                   element_initializer, &element_value)) {
                        return false;
                    }
                    if (*member_count < 0 ||
                        (size_t)*member_count >= member_capacity ||
                        !member_values) {
                        return false;
                    }
                    member_values[(*member_count)++] = element_value;
                }
            }
            if (array_initializer) return false;
            continue;
        }
        if (field->type->kind == TYPE_STRUCT) {
            ExprList* nested_initializer = NULL;
            Type* nested_type = NULL;
            if (field_initializer) {
                if (field_initializer->kind != EXPR_COMPOUND) return false;
                nested_type = field_initializer->compound_type
                    ? field_initializer->compound_type : field_initializer->type;
                if (nested_type &&
                    !type_is_compatible(field->type, nested_type)) {
                    return false;
                }
                nested_initializer = field_initializer->compound_init;
            }
            if (!cxx_structural_class_collect_member_values(
                    field->type, nested_initializer,
                    field_initializer && field_initializer->compound_value_init,
                    member_values, member_capacity, member_count)) {
                return false;
            }
            continue;
        }
        if (field_initializer) {
            if (type_is_floating(field->type)) {
                double floating_value;
                if (!eval_template_floating_expression(
                        field_initializer, NULL, NULL, NULL,
                        &floating_value)) {
                    return false;
                }
                if (!cxx_structural_floating_member_conversion_is_valid(
                        field_initializer, field->type, floating_value)) {
                    rcc_error(field_initializer->loc,
                              "narrowing conversion in structural class non-type template argument");
                    return false;
                }
                if (field->type->kind == TYPE_FLOAT) {
                    float narrowed = (float)floating_value;
                    uint32_t bits;
                    if (sizeof(narrowed) != (size_t)field->type->size) {
                        return false;
                    }
                    memcpy(&bits, &narrowed, sizeof(bits));
                    member_value = (int64_t)bits;
                } else if (field->type->kind == TYPE_DOUBLE) {
                    uint64_t bits;
                    if (sizeof(floating_value) !=
                        (size_t)field->type->size) {
                        return false;
                    }
                    memcpy(&bits, &floating_value, sizeof(bits));
                    memcpy(&member_value, &bits, sizeof(member_value));
                } else {
                    return false;
                }
            } else if (field->type->kind == TYPE_NULLPTR) {
                if (!cxx_expr_is_nullptr_constant(field_initializer)) {
                    return false;
                }
            } else if (field->type->kind == TYPE_PTR) {
                if (field->type->cxx_is_member_pointer) {
                    int64_t null_pointer_constant;
                    if (field_initializer->cxx_member_pointer_form) {
                        if (!cxx_structural_pointer_member_value(
                                field_initializer, field->type,
                                &member_value)) {
                            return false;
                        }
                    } else if (cxx_expr_is_nullptr_constant(
                                   field_initializer)) {
                        member_value = -1;
                    } else if (expr_eval_integer_constant(
                                   field_initializer,
                                   &null_pointer_constant) &&
                               null_pointer_constant == 0) {
                        member_value = -1;
                    } else {
                        return false;
                    }
                } else if (cxx_expr_is_nullptr_constant(field_initializer)) {
                    member_value = 0;
                } else if (expr_eval_integer_constant(
                               field_initializer, &member_value)) {
                    if (member_value != 0) return false;
                } else if (!cxx_structural_pointer_member_value(
                               field_initializer, field->type,
                               &member_value)) {
                    return false;
                }
            } else if (!expr_eval_integer_constant(
                           field_initializer, &member_value)) {
                return false;
            }
        }
        if (*member_count < 0 ||
            (size_t)*member_count >= member_capacity || !member_values) {
            return false;
        }
        member_values[(*member_count)++] = member_value;
    }
    return initializer == NULL;
}

static bool cxx_structural_class_count_member_values(
    const Type* type, size_t* member_count);

static bool cxx_structural_array_count_member_values(
    const Type* type, size_t* member_count) {
    size_t element_count = 1u;
    if (!type || !member_count) return false;
    if (type->kind != TYPE_ARRAY) {
        if (type->kind == TYPE_STRUCT) {
            return cxx_structural_class_count_member_values(
                type, member_count);
        }
        *member_count = 1u;
        return true;
    }
    if (!type->base || type->array_len <= 0 || type->array_bound ||
        !cxx_structural_array_count_member_values(type->base,
                                                  &element_count) ||
        element_count == 0u ||
        element_count > (size_t)INT_MAX / (size_t)type->array_len) {
        return false;
    }
    *member_count = (size_t)type->array_len * element_count;
    return true;
}

static bool cxx_structural_class_count_member_values(
    const Type* type, size_t* member_count) {
    const TypeParam* field;
    if (!type || type->kind != TYPE_STRUCT || !type->cxx_class ||
        !member_count) {
        return false;
    }
    for (field = type->cxx_class->fields; field; field = field->next) {
        if (field->is_static) continue;
        if (field->type->kind == TYPE_STRUCT) {
            if (!cxx_structural_class_count_member_values(
                    field->type, member_count)) {
                return false;
            }
        } else if (field->type->kind == TYPE_ARRAY) {
            size_t field_member_count = 0u;
            if (!cxx_structural_array_count_member_values(
                    field->type, &field_member_count) ||
                field_member_count > (size_t)INT_MAX - *member_count) {
                return false;
            }
            *member_count += field_member_count;
        } else {
            if (*member_count >= (size_t)INT_MAX) return false;
            ++*member_count;
        }
    }
    return true;
}

static bool cxx_template_non_type_constant_value(
    const Expr* expression, int64_t* value_out) {
    if (!expression || !value_out) return false;
    if (expr_eval_integer_constant((Expr*)expression, value_out)) return true;
    if (cxx_expr_is_nullptr_constant(expression)) {
        *value_out = 0;
        return true;
    }
    if (expression->kind == EXPR_COMPOUND) {
        Type* value_type = expression->compound_type
            ? expression->compound_type : expression->type;
        size_t member_capacity = 0u;
        int64_t* member_values = NULL;
        int member_count = 0;
        if (!cxx_structural_class_value_supported_subset(value_type) ||
            !cxx_structural_class_count_member_values(
                value_type, &member_capacity) ||
            member_capacity > SIZE_MAX / sizeof(*member_values)) {
            return false;
        }
        if (member_capacity != 0u) {
            member_values = ast_arena_alloc(
                member_capacity * sizeof(*member_values));
            if (!member_values) return false;
        }
        if (!cxx_structural_class_collect_member_values(
                value_type, expression->compound_init,
                expression->compound_value_init, member_values,
                member_capacity, &member_count)) {
            return false;
        }
        if (!cxx_structural_class_pack_member_values(
                value_type, member_values, member_count, value_out)) {
            return false;
        }
        return true;
    }
    return false;
}
